</script>

<template>

  <section class="bs-container bs-mt-lg" id="tech-stack">

    <h2 v-if="title" class="bs-h2 text-center md:text-left">{{ title }}</h2>

    <div class="bs-mt-md flex flex-wrap justify-center gap-4">

      <div
        v-for="(item, idx) in stack"
        :key="idx"
        class="group flex items-center gap-3 px-5 py-3.5 rounded-xl bg-bs-surface-2 border border-bs-surface-3 hover:border-transparent transition-all duration-300 cursor-default"
        :style="{ '--accent': item.color }"
      >
        <!-- Icon -->
        <span
          class="w-6 h-6 flex items-center justify-center shrink-0 transition-colors duration-300"
          :style="{ color: item.color }"
          v-html="iconMap[item.name]"
        />

        <!-- Name -->
        <span class="text-sm font-medium text-bs-foreground-dark group-hover:text-bs-foreground-light transition-colors duration-300 whitespace-nowrap">
          {{ item.name }}
        </span>

        <!-- Category dot -->
        <span
          class="w-1.5 h-1.5 rounded-full opacity-40 group-hover:opacity-100 transition-opacity duration-300"
          :style="{ backgroundColor: item.color }"
        />
      </div>

    </div>

  </section>

</template>

<style scoped>
.group:hover {
  box-shadow: 0 0 20px -5px color-mix(in srgb, var(--accent) 30%, transparent);
  border-color: color-mix(in srgb, var(--accent) 40%, transparent);
}
</style>
